head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거)
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.onpageload = function() {
	var totRow = 200;
	var totCol = grid1.getTotalCol();
	var arr = [];
	for (var i = 0; i < totRow; i++) {
		for (var j = 0; j < totCol; j++) {
			if (j != 0) {
				arr.push("index_" + i + "_" + j);
			} else {
				arr.push("");
			}
		}
	}
	grid1.setData(arr);
	grid1.setCellChecked(0, "chk", true);
	grid1.setCellChecked(4, "chk", true);
	grid1.setCellChecked(5, "chk", true);
	grid1.setCellChecked(6, "chk", true);
	grid1.setCellChecked(7, "chk", true);
	grid1.setCellChecked(9, "chk", true);
	grid1.setCellChecked(10, "chk", true);
	grid1.setCellChecked(12, "chk", true);
	grid1.setCellChecked(13, "chk", true);
};
scwin.select11_onviewchange = function(info) {
	var value = info.value;
	grid1.clearRowVisible();
	if (value == "1") {
	} else if (value == "2") {
		for (var i = 0; i < grid1.getTotalRow(); i++) {
			var chk = grid1.getCellChecked(i, 0);
			if (!chk) {
				grid1.setRowVisible(i, false);
			}
		}
	} else if (value == "3") {
		for (var i = 0; i < grid1.getTotalRow(); i++) {
			var chk = grid1.getCellChecked(i, 0);
			if (chk) {
				grid1.setRowVisible(i, false);
			}
		}
	}
};
scwin.compareValue = function(id1, id2) {
	if (scwin.__getDom($p.id + id1).textContent == scwin.__getDom($p.id + id2).textContent) {
		return false;
	}
	return true;
};
